        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Advertiser
        	// --------------------------------------
        	CompletableFuture<Advertiser> futureEntity = queryGateway.query(new FindAdvertiserQuery( new LoadAdvertiserFilter( summary.getAdvertiserId() ) ), ResponseTypes.instanceOf(Advertiser.class));
        	
        	entity = futureEntity.get();
